// 1. Obtener los datos del trigger y limpiar espacios
const triggerData = $('Telegram Trigger').first().json;
const rawText = triggerData.message.text ? triggerData.message.text.trim() : "";
const telegramId = triggerData.message.from.id;

// 2. Extraer de forma segura la pantalla actual del nodo anterior (Google Sheets)
const sessionInput = $('Leer Memoria Sesion').first().json;
const pantallaActual = sessionInput.pantalla_actual ? String(sessionInput.pantalla_actual).trim() : "explorando_menu";

// 3. Evaluar si estábamos esperando una cantidad
if (pantallaActual.startsWith("esperando_cantidad_")) {
    const productId = pantallaActual.replace("esperando_cantidad_", "").trim();

    // Convertir el texto limpio a número entero
    const cantidad = parseInt(rawText, 10);

    // 4. Validación de formato: verificar que sea un número real y mayor a 0
    if (isNaN(cantidad) || cantidad <= 0 || !Number.isInteger(cantidad)) {
        return {
            json: {
                telegram_id: telegramId,
                error: true,
                mensaje: "⚠️ Formato inválido. Por favor, escribe **solo un número entero** mayor a 0 (ej: 3)."
            }
        };
    }

    // 5. Cruzar con el Stock real del menú (usando 'Leer Menu1' y 'id_producto')
    const menuItems = $('Leer Menu1').all();
    const productoEncontrado = menuItems.find(item => String(item.json.id_producto).trim() === String(productId));

    if (!productoEncontrado) {
        return {
            json: {
                telegram_id: telegramId,
                error: true,
                mensaje: "⚠️ Error: El producto ya no existe en el catálogo."
            }
        };
    }

    const stockDisponible = parseInt(productoEncontrado.json.stock, 10) || 0;
    const nombreProducto = productoEncontrado.json.nombre || "producto";

    // -----------------------------------------------------------------
    // NUEVO: Calcular lo que ya tenía en el carrito acumulado de este producto
    // -----------------------------------------------------------------
    let cantidadYaEnCarrito = 0;
    const cartText = sessionInput && sessionInput.carrito_temporal ? String(sessionInput.carrito_temporal).trim() : "";

    if (cartText && !cartText.toLowerCase().includes("vacío")) {
        const lineas = cartText.split('\n');
        lineas.forEach(linea => {
            const match = linea.match(/(\d+)\s*-\s*Cantidad:\s*(\d+)/i);
            if (match) {
                const idExistente = match[1];
                const qtyExistente = parseInt(match[2], 10);
                if (String(idExistente).trim() === String(productId)) {
                    cantidadYaEnCarrito += qtyExistente;
                }
            }
        });
    }

    const cantidadTotalDeseada = cantidadYaEnCarrito + cantidad;

    // 6. Validar si la suma total supera el stock real
    if (cantidadTotalDeseada > stockDisponible) {
        return {
            json: {
                telegram_id: telegramId,
                error: true,
                mensaje: `⚠️ No hay suficiente stock acumulado.\n\n📦 *${nombreProducto}* tiene un límite de *${stockDisponible}* unidades en total.\n- Ya habías pedido: ${cantidadYaEnCarrito}\n- Intentaste agregar: ${cantidad}\n- Total requerido: ${cantidadTotalDeseada}\n\nPor favor, elige una cantidad menor.\n\n👉 Para revisar tu pedido o pagar y finalizar, envía: /carrito\n👉 Para agregar más cosas, envía: /menu`
            }
        };
    }

    // 7. Todo perfecto: validado stock y formato (Con sus guías de texto)
    return {
        json: {
            telegram_id: telegramId,
            error: false,
            product_id: productId,
            cantidad: cantidad,
            nuevo_estado: "explorando_menu",
            mensaje: `✅ ¡Listo! Se han agregado ${cantidad} unidades de *${nombreProducto}* al carrito.\n\n👉 Para revisar tu pedido o pagar y finalizar, envía: /carrito\n👉 Para agregar más cosas, envía: /menu`
        }
    };
}

// Paracaídas inteligente por si mandan un número fuera de tiempo
const esNumeroSuelto = /^\d+$/.test(rawText);
if (esNumeroSuelto) {
    return {
        json: {
            telegram_id: telegramId,
            error: true,
            mensaje: "⚠️ Has enviado un número, pero no estás seleccionando la cantidad de ningún producto en este momento. Usa /menu para ver las opciones. 🤖"
        }
